// Optimized for better data locality and fewer repeated memory accesses.
// Heavy work (R row update and trailing A update) is expressed as row-wise
// traversals over (i, j) to exploit the row-major layout of A and Q.
[[gnu::flatten, gnu::noinline]]
void kernel_gramschmidt(auto A, auto R, auto Q) {
	using namespace noarr;

	auto m = A | get_length<'i'>();
	auto n = A | get_length<'j'>();

	(void)m; // m is not explicitly needed, traversal takes care of bounds

	#pragma scop
	for (std::size_t k = 0; k < n; k++) {

		// Views of the k-th column of A and Q (A[:, k], Q[:, k]).
		// With the chosen layout (i outer, j inner), this is a strided
		// access, but the amount of work here is only O(m * n) overall.
		auto A_col_k = A ^ noarr::fix<'j'>(k);
		auto Q_col_k = Q ^ noarr::fix<'j'>(k);

		// nrm = 0;
		// for (i = 0; i < m; i++)
		//   nrm += A[i][k] * A[i][k];
		num_t nrm = (num_t)0.0;
		noarr::traverser(A_col_k).for_each([&](auto state) {
			num_t a_ik = A_col_k[state];
			nrm += a_ik * a_ik;
		});

		// R[k][k] = sqrt(nrm);
		num_t r_kk = std::sqrt(nrm);
		R[noarr::idx<'k', 'j'>(k, k)] = r_kk;

		// for (i = 0; i < m; i++)
		//   Q[i][k] = A[i][k] / R[k][k];
		noarr::traverser(A_col_k, Q_col_k).for_each([&](auto state) {
			Q_col_k[state] = A_col_k[state] / r_kk;
		});

		// Handle trailing columns j = k+1 .. n-1.
		// The original code:
		//
		// for (j = k + 1; j < n; j++) {
		//   R[k][j] = 0.0;
		//   for (i = 0; i < m; i++)
		//     R[k][j] += Q[i][k] * A[i][j];
		//   for (i = 0; i < m; i++)
		//     A[i][j] = A[i][j] - Q[i][k] * R[k][j];
		// }
		//
		// We rewrite the computation mathematically-equivalently as:
		//
		// // zero R[k][j] for j > k
		// for j = k+1..n-1: R[k][j] = 0;
		//
		// // accumulate the whole row R[k][j] using row-wise traversal
		// for i = 0..m-1:
		//   qik = Q[i][k];
		//   for j = k+1..n-1:
		//     R[k][j] += qik * A[i][j];
		//
		// // update A using the finished R row
		// for i = 0..m-1:
		//   qik = Q[i][k];
		//   for j = k+1..n-1:
		//     A[i][j] -= qik * R[k][j];
		//
		// This preserves the mathematical result (only changes summation
		// order), but lets us traverse A and R row-major (j inner), which
		// is cache-friendlier and vectorization-friendly.

		if (k + 1 < n) {
			const std::size_t start_j = k + 1;
			const std::size_t len_j   = n - start_j; // number of trailing columns

			// View of row k of R: R[k, :]
			auto R_row_k     = R ^ noarr::fix<'k'>(k);
			// View of the trailing part of that row: R[k, k+1 : n)
			auto R_row_tail  = R_row_k ^ noarr::slice<'j'>(start_j, len_j);

			// View of trailing columns of A: A[:, k+1 : n)
			auto A_tail_cols = A ^ noarr::slice<'j'>(start_j, len_j);

			// 1) Zero R[k][j] for j > k over the tail slice.
			noarr::traverser(R_row_tail).for_each([&](auto state) {
				R_row_tail[state] = (num_t)0.0;
			});

			// 2) Accumulate R[k][j] = sum_i Q[i][k] * A[i][j]
			//    using row-wise traversal (outer 'i', inner 'j').
			noarr::traverser(A_tail_cols, R_row_tail)
				.template for_dims<'i'>([&](auto row_trav) {
					// row_trav has 'i' fixed and iterates over 'j'
					// Q_col_k only depends on 'i', so we read it once per row.
					num_t qik = Q_col_k[row_trav.state()]; // Q[i][k], 'j' in state is ignored

					row_trav.for_each([&](auto state) {
						// state has both 'i' and 'j'; for:
						//   A_tail_cols[state] == A[i][j]
						//   R_row_tail[state]  == R[k][j] (same j, i ignored)
						R_row_tail[state] += qik * A_tail_cols[state];
					});
				});

			// 3) Update A[:, j] = A[:, j] - Q[:, k] * R[k][j]  for j > k
			//    again in a row-wise fashion.
			noarr::traverser(A_tail_cols, R_row_tail)
				.template for_dims<'i'>([&](auto row_trav) {
					num_t qik = Q_col_k[row_trav.state()]; // Q[i][k]

					row_trav.for_each([&](auto state) {
						A_tail_cols[state] -= qik * R_row_tail[state];
					});
				});
		}
	}
	#pragma endscop
}

