// QR Decomposition with Modified Gram-Schmidt
//
// Optimizations vs. the baseline:
//  - Keep the original data layout (row-major in 'j'), but *restructure* the
//    inner j>k loops to traverse rows (i) outside and columns (j) inside.
//    This matches the contiguous 'j' dimension and improves cache locality.
//  - Compute an entire row k of R (for j>k) at once, using a matrix-vector
//    style update:
//        r_kj = sum_i Q[i][k] * A[i][j]  for all j>k
//    in a single sweep over rows, then update A in a second sweep.
//  - Q[:,k] is read only once per row in each sweep, reducing repeated loads
//    compared to the original per-(k,j) column-wise loops.
//
// The mathematical algorithm (Modified Gram-Schmidt) is preserved exactly.
[[gnu::flatten, gnu::noinline]]
void kernel_gramschmidt(auto A, auto R, auto Q) {
	using namespace noarr;

	auto m = A | get_length<'i'>();
	auto n = A | get_length<'j'>();

	(void)m; // m is not explicitly needed, traversal takes care of bounds

	#pragma scop
	for (std::size_t k = 0; k < n; k++) {

		// ---------------------------------------------------------------------
		// Step 1: Compute column norm nrm = ||A[:,k]||_2^2
		// ---------------------------------------------------------------------
		num_t nrm = (num_t)0.0;

		// k-th column views of A and Q (A[:, k], Q[:, k])
		// A_col_k, Q_col_k have dimension 'i' only (rows).
		auto A_col_k = A ^ noarr::fix<'j'>(k);
		auto Q_col_k = Q ^ noarr::fix<'j'>(k);

		traverser(A_col_k).for_each([&](auto state) {
			num_t a_ik = A_col_k[state];
			nrm += a_ik * a_ik;
		});

		// ---------------------------------------------------------------------
		// Step 2: Normalize column k to get Q[:,k] and diagonal R[k][k]
		// ---------------------------------------------------------------------
		num_t r_kk = std::sqrt(nrm);
		R[noarr::idx<'k', 'j'>(k, k)] = r_kk;

		traverser(A_col_k, Q_col_k).for_each([&](auto state) {
			Q_col_k[state] = A_col_k[state] / r_kk;
		});

		// ---------------------------------------------------------------------
		// Step 3: For all columns j > k:
		//   - Compute R[k][j] = Q[:,k]^T * A[:,j]   (dot products)
		//   - Update A[:,j]  = A[:,j] - Q[:,k]*R[k][j]
		//
		// We do this in a *row-major* fashion to improve locality:
		//   (a) First sweep over rows i, accumulating all R[k][j] for j>k
		//   (b) Second sweep over rows i, updating all A[i][j], j>k
		//
		// The original column-wise loops:
		//   for j = k+1..n-1:
		//     r_kj = sum_i Q[i][k]*A[i][j]
		//     A[i][j] -= Q[i][k]*r_kj
		//
		// are mathematically equivalent to the row-major two-sweep form.
		// ---------------------------------------------------------------------

		// Number of remaining columns j > k
		std::size_t remaining_cols = n - (k + 1);
		if (remaining_cols == 0)
			continue; // no j > k, nothing to do for this k

		// A views restricted to columns j in {k+1, ..., n-1}
		//   A_after_k has dimensions 'i' (rows), 'j' (the sliced columns).
		auto A_after_k =
			A ^ noarr::slice<'j'>(k + 1, remaining_cols);

		// View of row k of R, restricted to j > k:
		//   R_row_k has dimension 'j' only (the same j-slice as A_after_k).
		auto R_row_k =
			R ^ noarr::fix<'k'>(k) ^ noarr::slice<'j'>(k + 1, remaining_cols);

		// Ensure R[k][j] for j>k starts from 0.0
		traverser(R_row_k).for_each([&](auto state) {
			R_row_k[state] = (num_t)0.0;
		});

		// ------------------ Phase 3a: compute R[k][j>k] ----------------------
		// r_kj = sum_i Q[i][k] * A[i][j]  for all j>k
		//
		// Implemented as:
		//   for each row i:
		//     q_ik = Q[i][k];
		//     for each column j>k:
		//       R[k][j] += q_ik * A[i][j];
		//
		// We express this with a traverser over (Q_col_k, A_after_k, R_row_k),
		// hoisting 'i' as the outer loop and iterating 'j' inside.
		traverser(Q_col_k, A_after_k, R_row_k)
			.template for_dims<'i'>([&](auto row_trav) {
				// row_trav: traverser with 'i' fixed, 'j' varying (where present)

				// Load Q[i][k] once per row and reuse for all columns j>k
				num_t q_ik = Q_col_k[row_trav];

				// Inner loop over columns j>k for this row i
				row_trav.for_each([&](auto state) {
					// state has 'i' and 'j'; R_row_k ignores 'i' and uses 'j'
					R_row_k[state] += q_ik * A_after_k[state];
				});
			});

		// ------------------ Phase 3b: update A[:, j>k] -----------------------
		// A[i][j] = A[i][j] - Q[i][k] * R[k][j]  for all j>k
		//
		// Same row-major structure as above:
		//   for each row i:
		//     q_ik = Q[i][k];
		//     for each column j>k:
		//       A[i][j] -= q_ik * R[k][j];
		traverser(Q_col_k, A_after_k, R_row_k)
			.template for_dims<'i'>([&](auto row_trav) {
				num_t q_ik = Q_col_k[row_trav];

				row_trav.for_each([&](auto state) {
					A_after_k[state] -= q_ik * R_row_k[state];
				});
			});
	}
	#pragma endscop
}

