	// A, Q:  M x N  (i x j), column-major: dims ('j' outer, 'i' inner)
	DEFINE_PROTO_STRUCT(a_layout, i_vec ^ j_vec);
	DEFINE_PROTO_STRUCT(q_layout, i_vec ^ j_vec);

