		R[idx<'k', 'j'>(k, k)] = r_kk;

		// 2) Normalize k-th column: Q[:, k] = A[:, k] / R[k][k]
		traverser(A_col_k, Q_col_k).for_each([&](auto s_i) {
			Q_col_k[s_i] = A_col_k[s_i] / r_kk;
		});

		// 3) For each j > k:
		//      R[k][j] = sum_i Q[i][k] * A[i][j]
		//      A[i][j] = A[i][j] - Q[i][k] * R[k][j]
		//
		// We implement the j-loop using the traverser of R with 'k' fixed.
		// To avoid extra branching for j <= k, we restrict the j-range
		// with a dynamic shift on dimension 'j'.
		//
		// trav_k_tail will only traverse j in [k+1, n), but the state
		// still contains the original global indices, so we can use it
		// directly with A, Q, and R.
		auto trav_k_tail = trav_k.order(shift<'j'>(k + 1));

		trav_k_tail.template for_dims<'j'>([&](auto trav_kj) {
			const std::size_t j = get_index<'j'>(trav_kj.state());
			// Now j satisfies j > k (or there are no iterations at all if k+1 >= n)

			// j-th column view of A: A[:, j]
			auto A_col_j = A ^ fix<'j'>(j);

			// 3a) Accumulate R[k][j] = dot(Q[:,k], A[:,j])
			num_t r_kj = (num_t)0.0;

			traverser(Q_col_k, A_col_j).for_each([&](auto s_i) {
				r_kj += Q_col_k[s_i] * A_col_j[s_i];
			});

			// Store R[k][j] using the traverser as an index
			R[trav_kj] = r_kj;

			// 3b) Update A[:, j] = A[:, j] - Q[:, k] * R[k][j]
			traverser(Q_col_k, A_col_j).for_each([&](auto s_i) {
				A_col_j[s_i] -= Q_col_k[s_i] * r_kj;
			});
		});
	});
	#pragma endscop
}

} // namespace


int main(int argc, char *argv[]) {
