	// problem size
	std::size_t m = M;
	std::size_t n = N;

	// set lengths for all dimensions used
	auto set_lengths =
		noarr::set_length<'i'>(m) ^
		noarr::set_length<'j'>(n) ^
		noarr::set_length<'k'>(n);

