		auto Q_col_k = Q ^ fix<'j'>(k);

		// ---------------------------------------------------------------------
		// 1) Compute the 2-norm of column k: nrm = sum_i A[i][k]^2
		// ---------------------------------------------------------------------
		num_t nrm = (num_t)0.0;

		traverser(A_col_k).for_each([&](auto state_i) {
			num_t a_ik = A_col_k[state_i];
			nrm += a_ik * a_ik;
		});

		// R[k][k] = sqrt(nrm);
		num_t r_kk = std::sqrt(nrm);
		R[idx<'k', 'j'>(k, k)] = r_kk;

		// ---------------------------------------------------------------------
		// 2) Normalize column k to obtain Q[:, k] = A[:, k] / R[k][k]
		//    We precompute the reciprocal to turn divisions into multiplications.
		// ---------------------------------------------------------------------
		const num_t inv_r_kk = (num_t)1.0 / r_kk;

