				traverser(Q_col_k, A_col_j).for_each([&](auto state_i) {
					r_kj = std::fma(Q_col_k[state_i], A_col_j[state_i], r_kj);
				});

				R_row_k[j_trav] = r_kj;

				traverser(Q_col_k, A_col_j).for_each([&](auto state_i) {
